  // sweeping the mix from all-T1 through uniform to all-T3 — pure expectation
  const pts = [];
  for (let m = 0; m <= 1.0001; m += 0.05) {
    let p;
    if (m <= 0.5) { const t = m * 2; p = [1 - t * 2 / 3, t / 3, t / 3]; }
    else { const t = (m - 0.5) * 2; p = [(1 - t) / 3, (1 - t) / 3, 1 / 3 + t * 2 / 3]; }
    let cost = 0, top = 0, served = 0, ws = 0, wt = 0;
    for (let i = 0; i < N; i++) {
      cost += p[0] * Cm[i][0] + p[1] * Cm[i][1] + p[2] * Cm[i][2];
      top += Cm[i][2];
      const s = diffs[i] <= 1 ? 1 : diffs[i] <= 2 ? p[1] + p[2] : p[2];
      served += s; ws += s * Cm[i][2]; wt += Cm[i][2];
    }
    pts.push([cost / top, served / N, ws / wt]);
  }
  return pts;
}

function loggedPolicy(Cm) {
  if (!Object.keys(TIER_OF_MODEL).length) return null;
  const diffsFair = gradeStruggleFree(); // see gradeStruggleFree: fairness fix
  const tiers = R.map(r => TIER_OF_MODEL[r.model] || 3);
  const main = evalPolicy(tiers, diffsFair, Cm);
  const alt = evalPolicy(R.map(r => TIER_OF_MODEL_ALT[r.model] || 3), diffsFair, Cm);
  // our current policy under the SAME struggle-free grading, for a fair sentence
  const ours = evalPolicy(C.rTiers, diffsFair, Cm);
  return { ...main, alt, ours };
}

// frontier: sweep the active method's own knob; each point = (costShare, served, wServed)
function frontier() {
  const { diffs, Cm, hRank } = C;
  const pts = [];
  const push = tiers => { const p = evalPolicy(tiers, diffs, Cm);
    return pts.push([p.costShare, p.served, p.wServed]); };
  if (state.method === 'ml-tau') {
    for (let tau = 0.30; tau <= 0.996; tau += 0.02) push(tauTiers(tau));
    return { pts, knob: 'τ' };
  }
  if (state.method === 'ml-lambda') {
    for (let k = 0; k < 40; k++) push(lambdaTiers(1e-4 * Math.pow(3e5, k / 39), Cm));
    return { pts, knob: 'λ' };
  }
  // cut-based methods (score / blend): sweep the Tier-3 cut. k-means has no
  // knob of its own — its "frontier" is the heuristic-cut reference sweep,
  // labeled as such so the curve can't impersonate the k-means dots.
  const base = state.method === 'blend'
    ? Float64Array.from({length: N}, (_, i) =>
        state.alpha * mlDiffRank[i] + (1 - state.alpha) * hRank[i])
    : C.hS;
  const sorted = Array.from(base).sort((a, b) => a - b);
  const ratio = state.rCuts[0] / (state.rCuts[1] || 1);
  for (let c2 = 0.30; c2 <= 1.0001; c2 += 0.025) {
    const cc2 = Math.min(c2, 1), q1 = quantile(sorted, cc2 * ratio), q2 = quantile(sorted, cc2);
    push(Array.from(base, s => s <= q1 ? 1 : s <= q2 ? 2 : 3));
  }
  return { pts, knob: state.method === 'kmeans'
    ? 'Tier-3 cut (heuristic reference — k-means itself has no knob)' : 'Tier-3 cut' };
}

// ---------- svg helpers ----------
const fmtPct = v => (100 * v).toFixed(1) + '%';
const fmt$ = v => '$' + v.toFixed(2);
const fmtSigned = v => (v >= 0 ? '+' : '') + v; // never prints '+-x'
const esc = s => String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/"/g,'&quot;');
// dataset text embedded INSIDE a data-tip needs a second encoding: the browser
// decodes the attribute once, and tip.innerHTML parses the result once more —
// single-encoded '<E>' placeholders vanished (and dataset markup would execute)
const escT = s => esc(esc(s));
const tip = document.getElementById('tip');
// one delegated handler serves every [data-tip] element, static or re-rendered
let tipEl = null;
document.addEventListener('mouseover', e => {
  const el = e.target.closest('[data-tip]');
  if (el !== tipEl) { tipEl = el; tip.style.display = el ? 'block' : 'none';
    if (el) tip.innerHTML = el.dataset.tip; }
});
document.addEventListener('mousemove', e => {
  if (!tipEl) return;
  const w = tip.offsetWidth, h = tip.offsetHeight;
