* { box-sizing: border-box; margin: 0; }
body.viz-root {
  background: var(--page); color: var(--ink-1);
  font: 14px/1.45 system-ui, -apple-system, "Segoe UI", sans-serif;
  padding: 20px clamp(12px, 3vw, 36px) 60px;
}
h1 { font-size: 21px; font-weight: 650; }
.sub { color: var(--ink-2); margin-top: 3px; max-width: 78ch; }
.chips { display: flex; gap: 8px; margin-top: 10px; flex-wrap: wrap; }
.chip { font-size: 12px; color: var(--ink-2); border: 1px solid var(--ring);
        background: var(--surface-1); border-radius: 999px; padding: 2px 10px; }
.tiles { display: grid; grid-template-columns: repeat(auto-fit, minmax(142px, 1fr));
         gap: 10px; margin: 18px 0 14px; }
.tile { background: var(--surface-1); border: 1px solid var(--ring);
        border-radius: 10px; padding: 11px 13px; }
.tile .lb { font-size: 12px; color: var(--ink-2); }
.tile .vl { font-size: 24px; font-weight: 600; margin-top: 2px; }
.tile .ct { font-size: 11.5px; color: var(--ink-3); margin-top: 2px; }
.layout { display: grid; grid-template-columns: 316px 1fr; gap: 14px; align-items: start; }
@media (max-width: 980px) { .layout { grid-template-columns: 1fr; } }
.panel, .card { background: var(--surface-1); border: 1px solid var(--ring); border-radius: 10px; }
.panel { padding: 13px 14px; margin-bottom: 12px; }
.panel h2, .card h2 { font-size: 13px; font-weight: 650; }
.panel .hint { font-size: 11.5px; color: var(--ink-3); margin: 2px 0 9px; }
.ctl { margin: 8px 0; }
.ctl label { display: flex; justify-content: space-between; font-size: 12px; color: var(--ink-2); }
.ctl label b { color: var(--ink-1); font-weight: 600; font-variant-numeric: tabular-nums; }
.ctl input[type=range] { width: 100%; accent-color: var(--s1); height: 20px; }
.seg { display: grid; grid-template-columns: 1fr 1fr; gap: 4px; margin: 6px 0 4px; }
.seg.cols3 { grid-template-columns: 1fr 1fr 1fr; }
.seg button { border: 1px solid var(--ring); border-radius: 8px; background: transparent;
              color: var(--ink-2); padding: 6px 2px; font: inherit; font-size: 12px; cursor: pointer; }
.seg button.on { background: var(--s1); color: #fff; border-color: var(--s1); }
.num { display: flex; align-items: center; justify-content: space-between; font-size: 12px;
       color: var(--ink-2); margin: 7px 0; gap: 8px; }
.num input { width: 62px; background: var(--page); color: var(--ink-1);
             border: 1px solid var(--ring); border-radius: 6px; padding: 3px 7px; font: inherit; }
.btn { border: 1px solid var(--ring); background: var(--page); color: var(--ink-2);
       border-radius: 7px; padding: 5px 10px; font: inherit; font-size: 12px; cursor: pointer; }
.btn:hover { color: var(--ink-1); }
.grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(330px, 1fr)); gap: 12px; }
.card { padding: 13px 14px 8px; min-width: 0; }
.card .desc { font-size: 11.5px; color: var(--ink-3); margin: 2px 0 6px; }
.card svg { width: 100%; height: auto; display: block; }
.legend { display: flex; gap: 14px; font-size: 12px; color: var(--ink-2); margin: 2px 0 4px; flex-wrap: wrap; }
.legend .k { display: inline-flex; align-items: center; gap: 5px; }
.legend .sw { width: 10px; height: 10px; border-radius: 3px; display: inline-block; }
.wide { grid-column: 1 / -1; }
table { width: 100%; border-collapse: collapse; font-size: 12.5px; }
th { text-align: left; color: var(--ink-3); font-weight: 500; font-size: 11.5px;
     border-bottom: 1px solid var(--grid); padding: 4px 8px; }
td { border-bottom: 1px solid var(--grid); padding: 5px 8px; vertical-align: top; }
td.n, th.n { text-align: right; font-variant-numeric: tabular-nums; }
.pv { color: var(--ink-2); max-width: 52ch; overflow: hidden; text-overflow: ellipsis;
      white-space: nowrap; display: block; }
.tierdot { display: inline-block; width: 9px; height: 9px; border-radius: 3px; margin-right: 5px; }
#tip { position: fixed; pointer-events: none; background: var(--surface-1); color: var(--ink-1);
       border: 1px solid var(--ring); border-radius: 8px; padding: 7px 10px; font-size: 12px;
       box-shadow: 0 4px 14px rgba(0,0,0,.18); max-width: 340px; z-index: 10; display: none;
       line-height: 1.4; }
#tip .t2 { color: var(--ink-2); } #tip .t3 { color: var(--ink-3); font-size: 11px; }
[data-tip] { cursor: help; }
svg [data-tip], .seg button[data-tip], input[data-tip] { cursor: pointer; }
.ctl label span[data-tip], .tile[data-tip], h2[data-tip], .chip[data-tip], .num[data-tip]
  { border-bottom: 1px dotted var(--ink-3); }
.tile[data-tip], h2[data-tip] { border-bottom: none; }
.tile[data-tip] .lb::after, h2[data-tip]::after, .card .desc[data-tip]::after
  { content: " ⓘ"; color: var(--ink-3); font-size: 10px; font-weight: 400; }
.sechead { margin: 18px 0 8px; font-size: 12px; font-weight: 650; letter-spacing: .08em;

