      const px = x(Math.min(p[0], 1)), py = y(p[yi]);
      path += (i ? 'L' : 'M') + px.toFixed(1) + ' ' + py.toFixed(1);
      dots += `<circle cx="${px.toFixed(1)}" cy="${py.toFixed(1)}" r="4" fill="${col}"
        stroke="${surf}" stroke-width="2"
        data-tip="${name}<br><b>${fmtPct(p[yi])}</b> at <b>${fmtPct(p[0])}</b> of all-Tier3 cost"/>`;
    });
    return `<path d="${path}" fill="none" stroke="${col}" stroke-width="2" stroke-linejoin="round"/>${dots}`;
  };
